import (
    "net/http"
    "path/filepath"
    "strings"
)

func downloadHandler(w http.ResponseWriter, r *http.Request) {
    filename := r.URL.Query().Get("file")
    baseDir := "/var/www/uploads"
    cleanPath := filepath.Clean(filepath.Join(baseDir, filename))
